// Регенерация: python3 scripts/generate_lead_tariffs.py
// Точные тарифы парка VIP BIKE (27 моделей): сутки, будни/выходные,
// слои 2–4/5–10/11–30 суток, почасовые пакеты 1ч/3ч/6ч/12ч, залог.

export interface BikeTariff {
  id: string;
  make: string;
  model: string;
  /** «79BIKE Falcon GT» — для вставки в тексты ответов. */
  displayName: string;
  /** Класс ТС из CSV (например, «Не требуются (электро-эндуро…)»). */
  licenseClass: string;
  /** Электро (для лимита пробега 150 км/сутки vs 200 км на бензине). */
  isElectric: boolean;
  daily: number | null;
  /** Сутки в будни (базовая ставка объявления). */
  weekday: number | null;
  /** Сутки в выходные (обычно +15–20%). */
  weekend: number | null;
  /** Ставка суток при аренде 2–4 суток. */
  days2to4: number | null;
  /** Ставка суток при аренде 5–10 суток. */
  days5to10: number | null;
  /** Ставка суток при аренде 11–30 суток (максимум скидки). */
  days11to30: number | null;
  /** Аренда 1 часа. */
  hour1: number | null;
  /** Пакет 3 часа. */
  hours3: number | null;
  /** Пакет 6 часов (полдня). */
  hours6: number | null;
  /** Пакет 12 часов. */
  hours12: number | null;
  /** Залог по модели, ₽ (null — уточнять). */
  deposit: number | null;
  /**
   * Наборы токенов для сопоставления с bikeTitle (lowercase, ё→е):
   * совпадение — если ЛЮБАЯ группа целиком входит в токены заголовка.
   */
  matchGroups: readonly (readonly string[])[];
}

